#include <string.h>

#include "cJSON.h"
#include "lodepng.h"

static void *xmalloc(size_t n) {
    void *p = malloc(n ? n : 1);
    if (!p) { fprintf(stderr, "out of memory\n"); exit(1); }
    return p;
}

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    if (n < 0) { fclose(f); fprintf(stderr, "cannot stat %s\n", path); exit(1); }
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)xmalloc((size_t)n + 1);
    size_t r = fread(buf, 1, (size_t)n, f);
    fclose(f);
    if ((long)r != n) { fprintf(stderr, "cannot read %s\n", path); exit(1); }
    buf[n] = '\0';
    if (out_len) *out_len = (size_t)n;
    return buf;
}

static double get_number(cJSON *obj, const char *key) {
    cJSON *it = cJSON_GetObjectItemCaseSensitive(obj, key);
    if (!it || !cJSON_IsNumber(it)) { fprintf(stderr, "weights.json: missing number '%s'\n", key); exit(1); }
    return it->valuedouble;
}

static float *get_float_array(cJSON *obj, const char *key, int expected, const char *what) {
    cJSON *arr = cJSON_GetObjectItemCaseSensitive(obj, key);
    if (!arr || !cJSON_IsArray(arr)) { fprintf(stderr, "weights.json: missing array '%s'\n", key); exit(1); }
    int n = cJSON_GetArraySize(arr);
    if (n != expected) { fprintf(stderr, "weights.json: '%s' has %d elements, expected %d\n", key, n, expected); exit(1); }
    float *v = (float *)xmalloc(sizeof(float) * (size_t)n);
    for (int i = 0; i < n; i++) {
        cJSON *it = cJSON_GetArrayItem(arr, i);
        if (!it || !cJSON_IsNumber(it)) { fprintf(stderr, "weights.json: '%s'[%d] is not a number (%s)\n", key, i, what); exit(1); }
        v[i] = (float)it->valuedouble;
    }
    return v;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s weights.json image.png\n", argc > 0 ? argv[0] : "cli_tool");
        return 1;
    }
    const char *weights_path = argv[1];
    const char *image_path = argv[2];

    size_t wlen = 0;
    char *wtext = read_file(weights_path, &wlen);
    cJSON *root = cJSON_ParseWithLength(wtext, wlen);
    free(wtext);
    if (!root) { fprintf(stderr, "weights.json: invalid JSON\n"); return 1; }

    int input_dim = (int)get_number(root, "input_dim");
    int hidden_dim = (int)get_number(root, "hidden_dim");
    int num_classes = (int)get_number(root, "num_classes");
    if (input_dim != 784 || hidden_dim <= 0 || num_classes <= 0) {
        fprintf(stderr, "weights.json: bad dims (%d,%d,%d)\n", input_dim, hidden_dim, num_classes);
        cJSON_Delete(root);
        return 1;
    }

    float *w1 = get_float_array(root, "input_layer_weight", hidden_dim * input_dim, "W1");
    float *b1 = get_float_array(root, "input_layer_bias", hidden_dim, "b1");
    float *w2 = get_float_array(root, "hidden_layer_weight", hidden_dim * hidden_dim, "W2");
    float *b2 = get_float_array(root, "hidden_layer_bias", hidden_dim, "b2");
    float *w3 = get_float_array(root, "output_layer_weight", num_classes * hidden_dim, "W3");
    float *b3 = get_float_array(root, "output_layer_bias", num_classes, "b3");
    cJSON_Delete(root);

    unsigned char *rgba = NULL;
    unsigned W = 0, H = 0;
    unsigned err = lodepng_decode32_file(&rgba, &W, &H, image_path);
    if (err) {
        fprintf(stderr, "cannot decode %s: %s\n", image_path, lodepng_error_text(err));
        return 1;
    }
    if (W == 0 || H == 0 || !rgba) { fprintf(stderr, "cannot decode %s\n", image_path); return 1; }

    /* Build 28x28 grayscale input in row-major order, scaled to [0,1] (matches training ToTensor). */
    float *x = (float *)xmalloc(sizeof(float) * 784);
    if (W == 28 && H == 28) {
        for (unsigned y = 0; y < 28; y++) {
            for (unsigned xx = 0; xx < 28; xx++) {
                unsigned char r = rgba[(y * 28 + xx) * 4 + 0];
                unsigned char g = rgba[(y * 28 + xx) * 4 + 1];
                unsigned char b = rgba[(y * 28 + xx) * 4 + 2];
                float gray = 0.299f * r + 0.587f * g + 0.114f * b;
                x[y * 28 + xx] = gray / 255.0f;
            }
        }
    } else {
        /* Bilinear resize of luminance to 28x28 for robustness. */
        float *lum = (float *)xmalloc(sizeof(float) * (size_t)W * H);
        for (unsigned y = 0; y < H; y++) {
            for (unsigned xx = 0; xx < W; xx++) {
                unsigned char r = rgba[(y * W + xx) * 4 + 0];
                unsigned char g = rgba[(y * W + xx) * 4 + 1];
                unsigned char b = rgba[(y * W + xx) * 4 + 2];
                lum[y * W + xx] = 0.299f * r + 0.587f * g + 0.114f * b;
            }
        }
        for (int y = 0; y < 28; y++) {
            float sy = ((y + 0.5f) * H / 28.0f) - 0.5f;
            int y0 = (int)sy; float fy = sy - y0;
            if (y0 < 0) { y0 = 0; fy = 0; }
            if (y0 > (int)H - 2) { y0 = (int)H - 2; fy = 1; }
            if (H == 1) { y0 = 0; fy = 0; }
            for (int xx = 0; xx < 28; xx++) {
                float sx = ((xx + 0.5f) * W / 28.0f) - 0.5f;
                int x0 = (int)sx; float fx = sx - x0;
                if (x0 < 0) { x0 = 0; fx = 0; }
                if (x0 > (int)W - 2) { x0 = (int)W - 2; fx = 1; }
                if (W == 1) { x0 = 0; fx = 0; }
                float p00 = lum[(size_t)y0 * W + x0];
                float p10 = lum[(size_t)y0 * W + (x0 + 1)];
                float p01 = lum[(size_t)(y0 + 1) * W + x0];
                float p11 = lum[(size_t)(y0 + 1) * W + (x0 + 1)];
                float g = (1 - fy) * ((1 - fx) * p00 + fx * p10) + fy * ((1 - fx) * p01 + fx * p11);
                x[y * 28 + xx] = g / 255.0f;
            }
        }
        free(lum);
    }
    free(rgba);

    float *h1 = (float *)xmalloc(sizeof(float) * (size_t)hidden_dim);
    float *h2 = (float *)xmalloc(sizeof(float) * (size_t)hidden_dim);
    float *out = (float *)xmalloc(sizeof(float) * (size_t)num_classes);

    for (int i = 0; i < hidden_dim; i++) {
        float s = b1[i];
        const float *row = &w1[(size_t)i * input_dim];
        for (int j = 0; j < input_dim; j++) s += row[j] * x[j];
        h1[i] = s > 0 ? s : 0;
    }
    for (int i = 0; i < hidden_dim; i++) {
        float s = b2[i];
        const float *row = &w2[(size_t)i * hidden_dim];
        for (int j = 0; j < hidden_dim; j++) s += row[j] * h1[j];
        h2[i] = s > 0 ? s : 0;
    }
    for (int i = 0; i < num_classes; i++) {
        float s = b3[i];
        const float *row = &w3[(size_t)i * hidden_dim];
        for (int j = 0; j < hidden_dim; j++) s += row[j] * h2[j];
        out[i] = s;
    }

    int pred = 0;
    for (int i = 1; i < num_classes; i++) {
        if (out[i] > out[pred]) pred = i;
    }
    printf("%d\n", pred);

    free(x); free(h1); free(h2); free(out);
    free(w1); free(b1); free(w2); free(b2); free(w3); free(b3);
    return 0;
}
